        array( 'en' => 'Built for growing teams.',          'translation' => 'Gemacht für wachsende Teams' ),
        array( 'en' => 'Save up to 40% with annual billing.', 'translation' => 'Sparen Sie bis zu 40 % mit jährlicher Abrechnung' ),
